def set_status_from_is_active(apps, schema_editor):
    Organisation = apps.get_model("organisations", "Organisation")
    # Existing organisations were usable before approvals existed: keep them working.
    Organisation.objects.filter(is_active=True).update(status="approved")
    Organisation.objects.filter(is_active=False).update(status="suspended")
    # The new case-insensitive name rule needs unique live names.
    seen = set()
    for org in Organisation.objects.exclude(status="rejected").order_by("id"):
        key = org.name.strip().lower()
        if key in seen:
            org.name = f"{org.name} ({org.id})"
            org.save(update_fields=["name"])
        seen.add(org.name.strip().lower())
    # Run the foreign key checks queued by these updates now, so PostgreSQL
    # allows the unique index below in the same transaction.
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


